import Domain
import Foundation
import OSLog

/// Orchestrates a post-diarization summarization pass.
///
/// Formats a ``DiarizedTranscript`` into speaker-labeled text, delegates
/// to the injected ``SummarizationEngine``, and persists the result via
/// the optional ``SummaryWriteRepository``. Storage failures are logged but
/// never prevent the summary from being returned to the caller.
public actor SummarizeMeetingUseCase {
    // MARK: - Dependencies

    private let summarization: any SummarizationEngine
    private let storage: (any SummaryWriteRepository)?
    private let config: SummaryConfig

    // MARK: - Logging

    private let logger = Logger(subsystem: "app.the-record", category: "Summarization")

    // MARK: - Init

    public init(
        summarization: any SummarizationEngine,
        config: SummaryConfig = .default,
        storage: (any SummaryWriteRepository)? = nil
    ) {
        self.summarization = summarization
        self.config = config
        self.storage = storage
    }

    // MARK: - Pre-warm

    /// Loads the model into memory so the first `summarize` call is instant.
    /// Safe to call multiple times — `loadModel` is idempotent when the same
    /// model is already loaded.
    public func prewarm() async throws {
        logger.info("Pre-warming summarization model: \(config.modelId, privacy: .public)")
        try await summarization.loadModel(config)
        logger.info("Summarization model pre-warm complete")
    }

    // MARK: - Summarize

    /// Summarizes a diarized transcript for the given recording.
    ///
    /// - Parameters:
    ///   - recordingId: Unique identifier of the recording (used for logging only).
    ///   - transcript: The diarized transcript to summarize.
    /// - Returns: A ``MeetingSummary`` produced by the summarization engine.
    /// - Throws: Any error from the engine — errors are never swallowed here.
    public func summarize(
        recordingId: RecordingID,
        transcript: DiarizedTranscript,
        meetingType: MeetingType = SummaryConfig.default.meetingType
    ) async throws -> MeetingSummary {
        logger.info("Starting summarization for recording \(recordingId, privacy: .private)")

        // Step 1: Ensure the model is loaded before summarizing.
        // Skip loadModel if prewarm() already loaded it — avoids a redundant
        // (and potentially expensive) second load call.
        if !(await summarization.isReady()) {
            try await summarization.loadModel(config)
        }

        // Step 2: Format segments as "[speakerId] text" lines.
        let formattedText = transcript.segments
            .map { "[\($0.speakerId)] \($0.text)" }
            .joined(separator: "\n")

        // Step 3: Extract unique speaker IDs in first-appearance order.
        var seen = Set<SpeakerID>()
        let uniqueSpeakers: [SpeakerID] = transcript.segments.compactMap { seg in
            seen.insert(seg.speakerId).inserted ? seg.speakerId : nil
        }

        logger.info(
            // swiftlint:disable:next line_length
            "Formatted \(transcript.segments.count, privacy: .public) segments across \(uniqueSpeakers.count, privacy: .public) speakers"
        )

        // Step 4: Delegate to the summarization engine.
        let summary = try await summarization.summarize(
            transcript: formattedText,
            speakers: uniqueSpeakers.map(\.rawValue),
            meetingType: meetingType
        )

        logger
            .info(
                // swiftlint:disable:next line_length
                "Summarization complete for recording \(recordingId, privacy: .public), model: \(summary.modelId, privacy: .public)"
            )

        if let storage {
            do {
                try await storage.saveSummary(for: recordingId, summary: summary)
                logger.info("Summary persisted for recording \(recordingId, privacy: .public)")
            } catch {
                logger
                    // swiftlint:disable:next line_length
                    .error("Failed to persist summary for \(recordingId, privacy: .private): \(error, privacy: .private)")
            }
        }

        return summary
    }
}

